        row, col = action
    else:
        row, col = action[0], action[1]

    old_char = board[row][col]

    if old_char == 'B':
        board[row][col] = 'g'
        for r in range(max(0, row-1), min(64, row+2)):
            for c in range(max(0, col-1), min(64, col+2)):
                if (r, c) != (row, col) and board[r][c] == 'B':
                    board[r][c] = 'g'
    elif old_char == 'p':
        board[row][col] = 'B'
        for r in range(max(0, row-1), min(64, row+2)):
            for c in range(max(0, col-1), min(64, col+2)):
                if (r, c) != (row, col) and board[r][c] == 'g':
                    board[r][c] = 'B'

